input.new_string:
// The ACTUAL ownedSession receipt (paravoxia.verifier.ownedSessionCleanupReceipt.v1)
// publishes state/cleanupCompleted/sessionStopped/cleanupError. It has NO 'stopped'
// field, so a missing/absent field must NEVER be read as success. Teardown is proven
// only by the positive conjunction below; every other state is retained as honest,
// unproved cleanup without claiming the probe-owned browser was torn down.
const r = teardown.receipt;
if (!r) {
  record.incompleteCleanup.push('no probe cleanup-receipt.json: the probe-owned browser teardown is UNPROVEN');
} else {
  const proven = r.state === 'stopped'
    && r.cleanupCompleted === true
    && r.sessionStopped === true
    && (r.cleanupError === null || r.cleanupError === undefined && false);
  teardown.receiptState = r.state ?? null;
  teardown.receiptCleanupCompleted = r.cleanupCompleted ?? null;
  teardown.receiptSessionStopped = r.sessionStopped ?? null;
  teardown.receiptCleanupError = r.cleanupError ?? null;
  if (!proven) {
    record.incompleteCleanup.push(
      `probe cleanup receipt does not prove teardown: state=${String(r.state)} ` +
      `cleanupCompleted=${String(r.cleanupCompleted)} sessionStopped=${String(r.sessionStopped)} ` +
      `cleanupError=${String(r.cleanupError ?? 'null').slice(0, 200)}`);
  }
  teardown.receiptProven = proven;
}
teardown.browserTeardownProven = Boolean(teardown.receiptProven)
  && (probe.exitCode !== null || probe.signalCode != null);

